Scope 
•
Scope: where a 
variable was declared, 
determines where it 
can be accessed from 
int numCalls = 0; 

int raiseToPower(int base, int exponent) { 
  numCalls = numCalls + 1; 
  int result = 1; 
  for (int i = 0; i < exponent; i = i + 1) { 
    result = result * base; 
  } 
  return result; 
} 

int max(int num1, int num2) { 
  numCalls = numCalls + 1; 
  int result; 
  if (num1 > num2) { 
    result = num1; 
  } 
  else { 
    result = num2; 
  } 
  return result; 
}

