Constructors 
• Can have multiple constructors 
class Point { 
public: 
  double x, y; 
  Point() { 
    x = 0.0; y = 0.0; cout << "default constructor" << endl; 
  } 
  Point(double nx, double ny) { 
    x = nx; y = ny; cout << "2-parameter constructor" << endl; 
  } 
}; 

int main() { 
  Point p; // default constructor 
  // p.x is 0.0, p.y is 0.0) 
  Point q(2.0, 3.0); // 2-parameter constructor 
  // q.x is 2.0, q.y is 3.0) 
}

• Recall that assigning one class instance to another 
copies all fields (default copy constructor) 
class Point { 
public: 
  double x, y; 
  Point() { 
    x = 0.0; y = 0.0; cout << "default constructor" << endl; 
  } 
  Point(double nx, double ny) { 
    x = nx; y = ny; cout << "2-parameter constructor" << endl; 
  } 
}; 

int main() { 
  Point q(1.0, 2.0); // 2-parameter constructor 
  Point r = q; 
  // r.x is 1.0, r.y is 2.0) 
} 
Invoking the copy constructor

class Point { 
public: 
  double x, y; 
  Point(double nx, double ny) { 
    x = nx; y = ny; cout << "2-parameter constructor" << endl; 
  } 
  Point(Point &o) { 
    x = o.x; y = o.y; cout << "custom copy constructor" << endl; 
  } 
}; 

int main() { 
  Point q(1.0, 2.0); // 2-parameter constructor 
  Point r = q; // custom copy constructor 
  // r.x is 1, r.y is 2 
} 
• You can define your own copy constructor

• Why make a copy constructor? Assigning all fields 
(default copy constructor) may not be what you want 
