void Xhandler() 
{ 
try { 
throw "hello"; // throw a char * 
} 
catch(const char *) { // catch a char * 
cout << "Caught char * inside Xhandler\n"; 
throw ; // rethrow char * out of function 
} 
} 
int main() 
{ 
cout << "Start\n";

try{ 
Xhandler(); 
} 
catch(const char *) { 
cout << "Caught char * inside main\n"; 
} 
cout << "End"; 
return 0; 
} 
